import{_ as a,o,c as l,a2 as r}from"./chunks/framework.DfxYo5JW.js";const p=JSON.parse('{"title":"MegaloEvolved とは？","description":"","frontmatter":{},"headers":[],"relativePath":"ja/index.md","filePath":"ja/index.md"}'),t={name:"ja/index.md"};function s(n,e,g,d,i,c){return o(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="megaloevolved-とは" tabindex="-1">MegaloEvolved とは？ <a class="header-anchor" href="#megaloevolved-とは" aria-label="Permalink to &quot;MegaloEvolved とは？&quot;">​</a></h1><p><strong>MegaloEvolved</strong>（npm パッケージ <code>@blamnetwork/megalo</code>）は、Halo の <strong>Megalo</strong> スクリプトを扱う TypeScript ライブラリです。Megalo は、Halo: Reach のゲームタイプやカスタムマップバリアントで使われるテキストベースのスクリプティング言語です。</p><h2 id="このパッケージが提供するもの" tabindex="-1">このパッケージが提供するもの <a class="header-anchor" href="#このパッケージが提供するもの" aria-label="Permalink to &quot;このパッケージが提供するもの&quot;">​</a></h2><ul><li><strong>パーサー</strong> — Megalo ソース（<code>.txt</code>）を AST に変換します（<a href="/MegaloEvolved/docs/ja/guide/parsing">ソースのパース</a>）。</li><li><strong>コンパイラ</strong> — プログラムからゲームバリアントまたはカスタムバリアントデータを構築します（<a href="/MegaloEvolved/docs/ja/guide/compiling">コンパイル</a>）。</li><li><strong>デコンパイラ</strong> — コンパイル済みバリアントデータから Megalo ソースを復元します（<a href="/MegaloEvolved/docs/ja/guide/decompiling">デコンパイル</a>）。</li><li><strong>BLF 連携</strong> — <a href="https://blam-network.github.io/blf/" target="_blank" rel="noreferrer">@blamnetwork/blf</a> 経由で BLF ファイル内のゲームタイプの抽出、パッチ、ラウンドトリップを行います（<a href="/MegaloEvolved/docs/ja/guide/gametypes">ゲームタイプと BLF</a>）。</li><li><strong>Megalo バージョン</strong> — Reach MCC および Xbox 360 TU1 に対応（<a href="/MegaloEvolved/docs/ja/guide/megalo-versions">Megalo バージョン</a>）。</li><li><strong>言語リファレンス</strong> — Bungie Megalo スクリプティングの概念とビルド別アクション表（<a href="/MegaloEvolved/docs/ja/language/">Megalo 言語</a>）。</li></ul><p>Megalo の構造体レイアウトと BLF チャンク I/O は <code>@blamnetwork/blf</code> および <a href="https://www.npmjs.com/package/@craftycodie/cstruct" target="_blank" rel="noreferrer">@craftycodie/cstruct</a> から提供され、npm 依存関係として自動インストールされます。</p><h2 id="はじめに" tabindex="-1">はじめに <a class="header-anchor" href="#はじめに" aria-label="Permalink to &quot;はじめに&quot;">​</a></h2><p><a href="/MegaloEvolved/docs/ja/guide/quick-start">インストールとクイックスタート</a> を参照してください。</p><p>リリース履歴: <a href="/MegaloEvolved/docs/ja/changelog">Changelog</a>。</p>',8)])])}const v=a(t,[["render",s]]);export{p as __pageData,v as default};
